// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.36;
contract C {
    function callValue(uint256 value) public {
        assembly { value := callvalue() }
    }
    function environment() external pure returns (uint256 value) {
        assembly { value := address() }
    }
    function storageRead() external pure returns (uint256 value) {
        assembly { value := sload(0) }
    }
    function stateWrite() external view {
        assembly { sstore(0, 1) }
    }
    function logWrite() external view {
        assembly { log0(0, 0) }
    }
    function memoryOnly() external {
        assembly { mstore(0, 1) }
    }
    modifier readsValue() {
        assembly { pop(callvalue()) }
        _;
    }
    function modified() public readsValue {}
}
